type SiteGlobals={site_name?:string;site_tagline?:string;logo_url?:string;email?:string;phone?:string;whatsapp?:string};
function useStoreSite(){const[site,setSite]=useState<SiteGlobals>({site_name:'YAQEEN',site_tagline:'A MORE MEANINGFUL LIFE'}),[nav,setNav]=useState<any>({}),[footer,setFooter]=useState<any>({});useEffect(()=>{if(!supabase)return;(async()=>{const[{data:setting},{data:docs}]=await Promise.all([supabase.from('site_settings').select('value').eq('key','website').maybeSingle(),supabase.from('website_documents').select('key,published').in('key',['navigation','footer']).not('published_at','is',null)]);setSite({...site,...(setting?.value||{})});for(const d of docs||[]){if(d.key==='navigation')setNav(d.published||{});if(d.key==='footer')setFooter(d.published||{})}})()},[]);return{site,nav,footer}}
