function NewsletterSection({section}:{section:any}){const[email,setEmail]=useState(''),[sending,setSending]=useState(false),[status,setStatus]=useState<'idle'|'success'|'error'>('idle');async function subscribe(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const clean=email.trim().toLowerCase();if(!clean||!supabase)return;setSending(true);setStatus('idle');const{error}=await supabase.from('newsletter_subscribers').insert({email:clean,consent_at:new Date().toISOString()});setSending(false);if(error&&error.code!=='23505'){setStatus('error');return}setEmail('');setStatus('success')}return <section className="container home-cms-newsletter"><div>{section.subheading&&<p className="eyebrow">{section.subheading}</p>}<h2>{section.heading}</h2>{section.body&&<p>{section.body}</p>}</div><form className="newsletter-signup" onSubmit={subscribe}><div className="newsletter-field"><input type="email" required maxLength={254} value={email} onChange={e=>{setEmail(e.target.value);setStatus('idle')}} placeholder="Your email address" aria-label="Email address"/><button className="button" disabled={sending}>{sending?'Joining…':(section.cta_text||'Subscribe')}</button></div>{status==='success'&&<span className="newsletter-success">You’re on the list. Thank you.</span>}{status==='error'&&<span className="newsletter-error">We couldn’t add you right now. Please try again.</span>}</form></section>}
