function SeoMetadata(){const loc=useLocation();useEffect(()=>{if(loc.pathname.startsWith('/admin')||loc.pathname==='/login')return;const path=loc.pathname||'/';const labels:Record<string,[string,string]>={'/':['YAQEEN — A more meaningful life','Thoughtful Islamic acrylic reminders designed to bring faith, meaning and intention into everyday life.'],'/shop':['Shop meaningful Islamic reminders | YAQEEN','Explore YAQEEN’s collection of thoughtful Islamic acrylic reminders and meaningful gifts.'],'/cart':['Your bag | YAQEEN','Review the meaningful reminders in your YAQEEN shopping bag.'],'/checkout':['Secure checkout | YAQEEN','Complete your YAQEEN order securely and provide your delivery details.'],'/order-confirmation':['Order confirmation | YAQEEN','Your YAQEEN order confirmation and next steps.'],'/search':['Search the collection | YAQEEN','Search YAQEEN for thoughtful Islamic acrylic reminders and meaningful gifts.'],'/about':['About YAQEEN | A more meaningful life','Discover the story and intention behind YAQEEN and our meaningful Islamic reminders.'],'/contact':['Contact YAQEEN','Get in touch with YAQEEN for product, order or delivery questions.'],'/faq':['Frequently asked questions | YAQEEN','Find answers to common questions about YAQEEN products, orders, payment and delivery.'],'/privacy':['Privacy Policy | YAQEEN','Read how YAQEEN handles information and browser storage when you use the storefront.'],'/terms':['Terms & Conditions | YAQEEN','Read the terms that apply when using the YAQEEN storefront and placing an order.'],'/under-construction':['Coming soon | YAQEEN','Something meaningful is taking shape at YAQEEN. This page will be available soon.']};let [title,description]=labels[path]||[path.startsWith('/products/')?'Islamic acrylic reminder | YAQEEN':'YAQEEN — A more meaningful life','Thoughtful Islamic acrylic reminders for a more meaningful life.'];document.title=title;const canonical=PUBLIC_ORIGIN+PUBLIC_BASE+(path==='/'?'/':path);const set=(selector:string,attr:string,value:string)=>{let el=document.head.querySelector<HTMLMetaElement>(selector);if(!el){el=document.createElement('meta');if(selector.includes('property='))el.setAttribute('property',selector.match(/property="([^"]+)/)?.[1]||'');else el.name=selector.match(/name="([^"]+)/)?.[1]||'';document.head.appendChild(el)}el.setAttribute(attr,value)};set('meta[name="description"]','content',description);set('meta[property="og:title"]','content',title);set('meta[property="og:description"]','content',description);set('meta[property="og:type"]','content',path.startsWith('/products/')?'product':'website');set('meta[property="og:url"]','content',canonical);set('meta[property="og:site_name"]','content','YAQEEN');set('meta[name="twitter:card"]','content','summary_large_image');set('meta[name="twitter:title"]','content',title);set('meta[name="twitter:description"]','content',description);let link=document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.appendChild(link)}link.href=canonical},[loc.pathname]);return null}

function Analytics(){const loc=useLocation();const[id,setId]=useState('');const[allowed,setAllowed]=useState(()=>{try{return localStorage.getItem('yaqeen-cookie-consent')==='accepted'}catch{return false}});useEffect(()=>{const onConsent=(event:Event)=>setAllowed((event as CustomEvent<string>).detail==='accepted');window.addEventListener('cookieconsentchange',onConsent);if(supabase)void supabase.from('site_settings').select('value').eq('key','website').maybeSingle().then(({data})=>setId(String(data?.value?.ga_measurement_id||data?.value?.google_analytics_id||'').trim()));return()=>window.removeEventListener('cookieconsentchange',onConsent)},[]);useEffect(()=>{if(!allowed||!/^G-[A-Z0-9]+$/i.test(id))return;const w=window as any;w.dataLayer=w.dataLayer||[];w.gtag=w.gtag||function(){w.dataLayer.push(arguments)};if(!document.querySelector('script[data-yaqeen-ga]')){const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(id);script.dataset.yaqeenGa='true';document.head.appendChild(script);w.gtag('js',new Date());w.gtag('config',id,{send_page_view:false,anonymize_ip:true})}w.gtag('event','page_view',{page_title:document.title,page_location:window.location.href,page_path:loc.pathname+loc.search})},[allowed,id,loc.pathname,loc.search]);return null}

function SiteFavicon(){useEffect(()=>{let live=true;const apply=(value:string)=>{let link=document.querySelector<HTMLLinkElement>('link[rel="icon"]');if(!value){link?.remove();return}if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=value};const onChange=(event:Event)=>apply((event as CustomEvent<string>).detail);window.addEventListener('sitefaviconchange',onChange);if(supabase)void supabase.from('site_settings').select('value').eq('key','website').maybeSingle().then(({data})=>{if(live)apply(data?.value?.favicon_url||'')});return()=>{live=false;window.removeEventListener('sitefaviconchange',onChange)}},[]);return null}
export default function App(){return <><SiteFavicon/><SeoMetadata/><Analytics/><Routes><Route path="/login" element={<Login/>}/><Route path="/admin/*" element={<Admin/>}/><Route path="*" element={<><Header/><main id="main"><Routes><Route path="/" element={<Home/>}/><Route path="/shop" element={<Products/>}/><Route path="/products/:slug" element={<ProductPage/>}/><Route path="/cart" element={<CartPage/>}/><Route path="/checkout" element={<CheckoutPage/>}/><Route path="/order-confirmation" element={<ConfirmationPage/>}/><Route path="/search" element={<SearchPage/>}/><Route path="/privacy" element={<LegalPage kind="privacy"/>}/><Route path="/terms" element={<LegalPage kind="terms"/>}/><Route path="/under-construction" element={<UnderConstruction/>}/><Route path="/:page" element={<ContentPage/>}/><Route path="*" element={<NotFound/>}/></Routes></main><Footer/><CookieConsent/></>}/></Routes></>}
type SiteGlobals={site_name?:string;site_tagline?:string;logo_url?:string;email?:string;phone?:string;whatsapp?:string};
function useStoreSite(){const[site,setSite]=useState<SiteGlobals>({site_name:'YAQEEN',site_tagline:'A MORE MEANINGFUL LIFE'}),[nav,setNav]=useState<any>({}),[footer,setFooter]=useState<any>({});useEffect(()=>{if(!supabase)return;(async()=>{const[{data:setting},{data:docs}]=await Promise.all([supabase.from('site_settings').select('value').eq('key','website').maybeSingle(),supabase.from('website_documents').select('key,published').in('key',['navigation','footer']).not('published_at','is',null)]);setSite({...site,...(setting?.value||{})});for(const d of docs||[]){if(d.key==='navigation')setNav(d.published||{});if(d.key==='footer')setFooter(d.published||{})}})()},[]);return{site,nav,footer}}
function Brand({site,logoUrl}:{site?:SiteGlobals;logoUrl?:string}){const logo=logoUrl||site?.logo_url;return <Link className={'brand '+(logo?'brand-has-logo':'')} to="/">{logo?<img className="brand-logo" src={logo} alt={site?.site_name||'YAQEEN'} decoding="async"/>:<><span className="arabic" lang="ar" dir="rtl">يقين</span><span>{site?.site_name||'YAQEEN'}</span><small>{site?.site_tagline||'A MORE MEANINGFUL LIFE'}</small></>}</Link>}
function Header(){const[o,setO]=useState(false),{site,nav}=useStoreSite(),[cart,setCart]=useState<HeaderCartItem[]>(readHeaderCart);useEffect(()=>{const sync=()=>setCart(readHeaderCart());window.addEventListener('cartchange',sync);window.addEventListener('storage',sync);return()=>{window.removeEventListener('cartchange',sync);window.removeEventListener('storage',sync)}},[]);const cartCount=cart.reduce((n,i)=>n+Number(i.quantity||0),0),cartTotal=cart.reduce((n,i)=>n+Number(i.price||0)*Number(i.quantity||0),0);const links=(nav.links?.length?nav.links:[{url:'/',label:'Home'},{url:'/shop',label:'Shop'},{url:'/about',label:'About'}]);return <><div className="announcement"><span>{nav.announcement||'LITTLE REMINDERS. LASTING MEANING.'}</span></div><header className="site-header"><div className="container store-nav-shell"><Brand site={site} logoUrl={nav.logo_url}/><nav className="desktop-nav" aria-label="Main navigation">{links.map((x:any)=><Link key={x.url+x.label} to={x.url}>{x.label}</Link>)}</nav><div className="header-actions"><Link className="store-nav-icon bag-nav-link" to="/cart" aria-label="Cart" data-tooltip="Bag"><span className="bag-icon-wrap"><ShoppingBag size={18}/>{cartCount>0&&<b className="bag-count">{cartCount}</b>}</span>{cartCount>0&&<small className="bag-total">{headerMoney(cartTotal)}</small>}</Link><button className="store-nav-icon mobile-menu-button" onClick={()=>setO(true)} aria-label="Menu"><Menu size={20}/></button></div></div></header>{o&&<><div className="mobile-menu-backdrop" onClick={()=>setO(false)}/><aside className="mobile-nav-drawer"><div className="mobile-drawer-brand"><Brand site={site} logoUrl={nav.logo_url}/><button className="store-nav-icon" onClick={()=>setO(false)} aria-label="Close menu">×</button></div><p className="mobile-nav-kicker">EXPLORE</p><nav>{links.map((x:any)=><Link key={x.url+x.label} onClick={()=>setO(false)} to={x.url}>{x.label}<span>→</span></Link>)}</nav><div className="mobile-nav-quick"><Link onClick={()=>setO(false)} to="/cart"><ShoppingBag size={17}/>Your bag</Link></div></aside></>}</>}
function Footer(){const{site,footer}=useStoreSite();const links=(footer.links?.length?footer.links:[{url:'/about',label:'Our story'},{url:'/contact',label:'Contact'},{url:'/faq',label:'FAQs'}]);return <footer className="footer modern-footer"><div className="container footer-main"><div className="footer-brand-column"><Brand site={site} logoUrl={footer.logo_url}/><p className="footer-statement">{footer.body||'Thoughtfully made. Meaningfully kept.'}</p><span className="footer-accent-line"/></div><div className="footer-link-column"><p className="footer-heading">{footer.links_heading||'Explore'}</p><nav>{links.map((x:any)=><Link key={x.url+x.label} to={x.url}>{x.label}<span>↗</span></Link>)}</nav></div><div className="footer-contact-column"><p className="footer-heading">{footer.contact_heading||'Stay connected'}</p><p className="footer-contact-copy">{footer.contact_text||'Questions, orders or something meaningful in mind? We’d love to hear from you.'}</p><div className="footer-contact-links">{site.email&&<a href={'mailto:'+site.email}>{site.email}</a>}{site.phone&&<a href={'tel:'+site.phone.replace(/\s/g,'')}>{site.phone}</a>}{site.whatsapp&&<a className="footer-whatsapp" href={'https://wa.me/'+site.whatsapp.replace(/[^0-9]/g,'')} target="_blank" rel="noreferrer">WhatsApp <span>↗</span></a>}</div></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} {site.site_name||'YAQEEN'} / يقين</span><nav className="footer-legal-links" aria-label="Legal"><Link to="/privacy">Privacy</Link><Link to="/terms">Terms</Link></nav><span>{footer.bottom_text||site.site_tagline||'A MORE MEANINGFUL LIFE'}</span></div></footer>}
function Page({title}:{title:string}){return <section className="section"><h1>{title}</h1><p>This section is being migrated from the original YAQEEN application.</p></section>}
function LegalPage({kind}:{kind:'privacy'|'terms'}){const privacy=kind==='privacy';return <article className="container legal-page"><p className="eyebrow">YAQEEN / LEGAL</p><h1>{privacy?'Privacy Policy':'Terms & Conditions'}</h1><p className="legal-updated">Last updated: 30 September 2026</p>{privacy?<><section><h2>Information we collect</h2><p>When you place an order or contact YAQEEN, we may receive information you provide such as your name, contact details, delivery information and message content. The site may also use essential browser storage needed for features such as your shopping bag and consent preference.</p></section><section><h2>How information is used</h2><p>Information is used to provide the storefront, process and fulfil orders, respond to enquiries, maintain security and improve the service. Payment information may be handled by the payment service presented during checkout rather than stored directly by YAQEEN.</p></section><section><h2>Service providers</h2><p>YAQEEN may rely on hosting, database, delivery, payment or communication providers to operate the service. Information is shared with them only as needed to provide those functions.</p></section><section><h2>Your choices</h2><p>You can decline optional cookies from the consent banner. For questions about personal information or requests concerning it, use the contact details published on the <Link to="/contact">Contact page</Link>.</p></section><section><h2>Changes</h2><p>This policy may be updated as the website and its services change. The latest version will be published on this page.</p></section></>:<><section><h2>Using the website</h2><p>By using the YAQEEN storefront, you agree to use it lawfully and not interfere with its operation, security or other customers.</p></section><section><h2>Products and availability</h2><p>Product descriptions, prices and availability are presented as accurately as possible. Availability can change, and an order may require confirmation before fulfilment.</p></section><section><h2>Orders, payment and delivery</h2><p>The checkout information shown at the time of purchase forms part of your order. Applicable payment and delivery options are presented during checkout. Please review your details before submitting an order.</p></section><section><h2>Content</h2><p>YAQEEN branding, product imagery, written content and designs may not be reproduced or used commercially without permission except where applicable law permits it.</p></section><section><h2>Questions</h2><p>For order or terms questions, contact YAQEEN through the <Link to="/contact">Contact page</Link>.</p></section></>}</article>}
function UnderConstruction(){return <section className="construction-page"><span className="construction-orbit construction-orbit-one"/><span className="construction-orbit construction-orbit-two"/><div className="construction-grain"/><div className="construction-card"><div className="construction-brand"><span className="construction-mark" lang="ar" dir="rtl">يقين</span><span>YAQEEN</span></div><p className="eyebrow">A MORE MEANINGFUL SPACE IS ON ITS WAY</p><h1>Something meaningful<br/><em>is taking shape.</em></h1><p className="construction-copy">We’re thoughtfully preparing a new YAQEEN experience — a quiet space for little reminders with lasting meaning.</p><div className="construction-divider"><span>✦</span></div><p className="construction-note">We’ll be ready soon. Until then, stay close.</p><div className="construction-actions"><Link className="button" to="/">Return home <span>→</span></Link><Link className="construction-contact" to="/contact">Contact us <span>↗</span></Link></div><div className="construction-bottom"><span>THOUGHTFULLY MADE</span><i/><span>MEANINGFULLY KEPT</span></div></div></section>}
function NotFound(){return <section className="container not-found-page"><p className="eyebrow">404 / PAGE NOT FOUND</p><span className="not-found-mark" lang="ar" dir="rtl">يقين</span><h1>This page wandered off.</h1><p>The page you’re looking for doesn’t exist or may have moved.</p><div className="not-found-actions"><Link className="button" to="/">Return home</Link><Link className="secondary-button" to="/shop">Explore the collection</Link></div></section>}
function CookieConsent(){const[choice,setChoice]=useState<string|null>(()=>{try{return localStorage.getItem('yaqeen-cookie-consent')}catch{return null}});if(choice)return null;const choose=(value:'essential'|'accepted')=>{try{localStorage.setItem('yaqeen-cookie-consent',value)}catch{}setChoice(value);window.dispatchEvent(new CustomEvent('cookieconsentchange',{detail:value}))};return <aside className="cookie-consent" role="dialog" aria-label="Cookie preferences" aria-live="polite"><div><strong>Your privacy matters.</strong><p>YAQEEN uses essential browser storage for the shopping experience. Optional cookies will only be enabled after you accept them.</p><Link to="/privacy">Read our Privacy Policy</Link></div><div className="cookie-actions"><button className="secondary-button" onClick={()=>choose('essential')}>Essential only</button><button className="primary-button" onClick={()=>choose('accepted')}>Accept optional</button></div></aside>}
function HomeProductSection({section}:{section:any}){
 const[items,setItems]=useState<P[]>([]),[loading,setLoading]=useState(true),[failed,setFailed]=useState(false);
 useEffect(()=>{let live=true;if(!supabase){setLoading(false);return}setLoading(true);setFailed(false);(async()=>{
  let q=supabase.from('products').select('id,title,slug,price,shape,bestseller,arabic_title,product_images(id,url,alt,position),product_variants(id,active,image_url,color,sku,product_variant_images(id,url,alt,position))').eq('status','Active');
  if(section.selection==='top')q=q.order('featured',{ascending:false});
  q=q.order('created_at',{ascending:false}).limit(6);
  if(section.selection==='bestseller')q=q.eq('bestseller',true);
  if(section.selection==='new_arrival')q=q.eq('new_arrival',true);
  if(Array.isArray(section.product_ids)&&section.product_ids.length)q=q.in('id',section.product_ids);
  const{data,error}=await q;if(live){const loaded=(data||[]) as P[];setItems(loaded);setFailed(Boolean(error));setLoading(false);warmImageCache(loaded.map(p=>[...(p.product_images||[])].sort((a,b)=>a.position-b.position)[0]?.url))}
 })();return()=>{live=false}},[section.selection,JSON.stringify(section.product_ids||[])]);
 if(!loading&&!failed&&!items.length)return null;
 return <section className="home-cms-section home-products container"><div className="home-section-head"><div>{section.subheading&&<p className="eyebrow">{section.subheading}</p>}<h2>{section.heading}</h2></div><Link className="home-text-link" to={section.cta_url||'/shop'}>{section.cta_text||'Explore the collection'} <ChevronRight size={18}/></Link></div>
 {loading?<BrandLoader label="Loading the collection"/>:failed?<p role="status">The collection is temporarily unavailable. <Link to="/shop">Visit the shop</Link></p>:<div className="store-product-grid">{items.map(p=>{const productImages=[...(p.product_images||[])].sort((a,b)=>a.position-b.position),variantImages=(p.product_variants||[]).filter(v=>v.active).flatMap(v=>v.product_variant_images?.length?[...v.product_variant_images].sort((a,b)=>(a.position||0)-(b.position||0)):v.image_url?[{id:'legacy-'+v.id,url:v.image_url,alt:v.color||v.sku||p.title,position:0}]:[]),cardImages=[...productImages,...variantImages];return <Link className="store-product-card" key={p.id} to={'/products/'+p.slug}><div className={'store-product-image '+(cardImages.length>1?'card-variant-carousel':'')}>{cardImages.length?<div className="card-variant-strip card-slideshow"><><picture className="card-mobile-image"><StoreImageView src={cardImages[0].url} alt={cardImages[0].alt||p.title} fetchPriority="low" sizes="(max-width: 700px) 92vw, 33vw"/></picture><div className="card-desktop-slides">{cardImages.map((img,index)=><StoreImageView key={img.id+'-'+index} src={img.url} alt={img.alt||p.title} fetchPriority="low" sizes="33vw" style={{animationDelay:(index*3)+'s'}}/>)}</div></></div>:<div className="placeholder"><span className="arabic">{p.arabic_title||'يقين'}</span><small>YAQEEN</small></div>}{p.bestseller&&<span className="badge">Much loved</span>}</div><div className="home-product-info"><div className="home-product-copy"><h3 dir="auto">{p.title}</h3></div>{p.price!=null&&<strong className="home-product-price" dir="ltr">{headerMoney(p.price)}</strong>}</div><span className="home-product-action">View product <ChevronRight size={15}/></span></Link>})}</div>}</section>
}
function HomeHero({section}:{section:any}){
 const[product,setProduct]=useState<P|null>(null);
 useEffect(()=>{let live=true;if(supabase)void supabase.from('products').select('id,title,slug,price,product_images(id,url,alt,position)').eq('status','Active').order('created_at',{ascending:false}).limit(1).then(({data})=>{if(live)setProduct(data?.[0] as P||null)});return()=>{live=false}},[]);
 const image=section.image||[...(product?.product_images||[])].sort((a,b)=>a.position-b.position)[0]?.url;
 return <section className="home-editorial-hero container"><div className="home-hero-copy"><p className="eyebrow">{section.subheading||'YAQEEN / A MORE MEANINGFUL LIFE'}</p><h1>{String(section.heading||'Little reminders.\nMeaningful moments.').split('\n').map((line,i)=><span key={i}>{line}</span>)}</h1><p className="home-hero-description">{section.body||'Thoughtful Islamic acrylic pieces for a more peaceful and purposeful life.'}</p><div className="home-hero-actions"><Link className="button" to={section.cta_url||'/shop'}>{section.cta_text||'Shop the collection'} <ChevronRight size={18}/></Link><Link className="home-text-link" to="/about">The story of YAQEEN</Link></div><div className="home-hero-note"><span className="arabic" lang="ar" dir="rtl">يقين</span><p>Faith in the everyday.<br/><span>A little reminder to keep close.</span></p></div></div><div className="home-hero-visual">{image?<StoreImageView src={image} alt={section.image?'YAQEEN acrylic collection':product?.title||'YAQEEN acrylic reminder'} fetchPriority="high" loading="eager" sizes="(max-width: 800px) 100vw, 52vw"/>:<div className="home-hero-wordmark"><span className="arabic" lang="ar">{section.arabic||'يقين'}</span><span>A MORE MEANINGFUL LIFE</span></div>}<div className="home-visual-caption"><span>OBJECTS WITH INTENTION</span>{product&&!section.image?<Link to={'/products/'+product.slug}>Explore this piece <ChevronRight size={17}/></Link>:<span>Made to mean something.</span>}</div></div></section>
}
function NewsletterSection({section}:{section:any}){const[email,setEmail]=useState(''),[sending,setSending]=useState(false),[status,setStatus]=useState<'idle'|'success'|'error'>('idle');async function subscribe(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const clean=email.trim().toLowerCase();if(!clean||!supabase)return;setSending(true);setStatus('idle');const{error}=await supabase.from('newsletter_subscribers').insert({email:clean,consent_at:new Date().toISOString()});setSending(false);if(error&&error.code!=='23505'){setStatus('error');return}setEmail('');setStatus('success')}return <section className="container home-cms-newsletter"><div>{section.subheading&&<p className="eyebrow">{section.subheading}</p>}<h2>{section.heading}</h2>{section.body&&<p>{section.body}</p>}</div><form className="newsletter-signup" onSubmit={subscribe}><div className="newsletter-field"><input type="email" required maxLength={254} value={email} onChange={e=>{setEmail(e.target.value);setStatus('idle')}} placeholder="Your email address" aria-label="Email address"/><button className="button" disabled={sending}>{sending?'Joining…':(section.cta_text||'Subscribe')}</button></div>{status==='success'&&<span className="newsletter-success">You’re on the list. Thank you.</span>}{status==='error'&&<span className="newsletter-error">We couldn’t add you right now. Please try again.</span>}</form></section>}
function HomeSection({section}:{section:any}){
 if(section.enabled===false)return null;
 if(section.type==='products')return <HomeProductSection section={section}/>;
 if(section.type==='hero')return <HomeHero section={section}/>;
 if(section.type==='banner')return <section className="home-cms-banner"><div className="container"><p className="eyebrow">{section.subheading||'A THOUGHTFUL PAUSE'}</p><h2>{section.heading}</h2>{section.body&&<p>{section.body}</p>}{section.cta_text&&<Link className="button" to={section.cta_url||'/shop'}>{section.cta_text} <ChevronRight size={18}/></Link>}</div></section>;
 if(section.type==='story')return <section className="container home-cms-story"><div className="home-story-symbol">{section.image?<StoreImageView className="home-section-image" src={section.image} alt="The story of YAQEEN" sizes="(max-width: 800px) 92vw, 45vw"/>:<><span className="arabic" lang="ar" dir="rtl">{section.arabic||'يقين'}</span><p>Yaqeen / Certainty</p></>}</div><div>{section.subheading&&<p className="eyebrow">{section.subheading}</p>}<h2>{section.heading}</h2>{section.body&&<p>{section.body}</p>}{section.cta_text&&<Link className="home-text-link" to={section.cta_url||'/about'}>{section.cta_text} <ChevronRight size={18}/></Link>}</div></section>;
 if(section.type==='newsletter')return <NewsletterSection section={section}/>;return null
}
const defaultHomeSections=[{id:'hero',type:'hero',heading:'Little reminders.\nMeaningful moments.',body:'Thoughtful Islamic acrylic pieces for a more peaceful and purposeful life.',cta_text:'Shop the collection',cta_url:'/shop'},{id:'products',type:'products',heading:'Find your everyday reminder.',subheading:'THE COLLECTION',cta_text:'Shop all reminders',cta_url:'/shop'},{id:'story',type:'story',subheading:'THE STORY OF YAQEEN',heading:'Made to mean something.',body:'Yaqeen means certainty. Thoughtful pieces that bring faith and meaning into the spaces you spend time in.',cta_text:'Our story',cta_url:'/about'}];
function homeShoppingSections(sections:any[]){
 const groups=[
  {id:'top-products',selection:'top',heading:'Top picks',subheading:'FIND YOUR EVERYDAY REMINDER'},
  {id:'new-arrivals',selection:'new_arrival',heading:'New arrivals',subheading:'JUST ADDED'},
  {id:'bestsellers',selection:'bestseller',heading:'Bestsellers',subheading:'CUSTOMER FAVOURITES'}
 ].map(group=>({type:'products',cta_text:'Shop all products',cta_url:'/shop',...sections.find(s=>s.type==='products'&&s.selection===group.selection),...group}));
 const other=sections.filter(s=>s.type!=='products');
 const heroIndex=other.findIndex(s=>s.type==='hero');
 other.splice(heroIndex+1,0,...groups);
 return other;
}
function Home(){const[sections,setSections]=useState<any[]|null>(null);useEffect(()=>{let live=true;if(!supabase){setSections(defaultHomeSections);return}(async()=>{const{data}=await supabase.from('website_documents').select('published').eq('key','homepage').not('published_at','is',null).maybeSingle();if(live)setSections((data?.published as any)?.sections?.length?(data?.published as any).sections:defaultHomeSections)})();return()=>{live=false}},[]);return <div className="home-redesign">{sections===null?<div className="container home-loading"><BrandLoader label="Loading home page"/></div>:homeShoppingSections(sections).map((section:any,i:number)=><HomeSection key={section.id||i} section={section}/>)}</div>}
function Login(){const nav=useNavigate();const[username,setUsername]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');const[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setError('');if(!configured||!supabase){setError('Supabase is not configured. Add VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY to .env.local, then restart the development server.');return}setBusy(true);try{const{error}=await supabase.auth.signInWithPassword({email:`${username.trim().toLowerCase()}@staff.yaqeen.invalid`,password});if(error)setError('Invalid username or password.');else nav('/admin/',{replace:true})}catch{setError('Unable to connect to Supabase. Check your local environment and internet connection.')}finally{setBusy(false)}}return <main className="login-wrap"><form className="login-card" onSubmit={submit}><Link className="brand" to="/">YAQEEN <span>يقين</span></Link><p className="eyebrow">YAQEEN WORKSPACE</p><h1>Staff sign in</h1><label>Username<input autoComplete="username" required value={username} onChange={e=>setUsername(e.target.value)}/></label><label>Password<input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></label>{error&&<p className="form-error">{error}</p>}<button className="primary-button" disabled={busy}>{busy?'Signing in…':'Sign in'}</button></form></main>}

const links=[['Dashboard','',null,LayoutDashboard],['Categories','categories','products.view',ClipboardList],['Products','products','products.view',Package],['Inventory','inventory','inventory.view',Package],['Design Library','designs','designs.view',Layers],['Messages','inbox','customers.view',Users],['Orders','orders','orders.view',ShoppingBag],['Production','production','production.view',Layers],['Customers','customers','customers.view',Users],['Delivery','deliveries','deliveries.view',Truck],['Payments','payments','payments.view',Wallet],['Website','website','website.view',Globe],['Reports','reports','reports.view',BarChart3],['Users & Roles','users','users.view',Shield],['Audit Log','audit','audit.view',ClipboardList],['Settings','settings','settings.view',Settings]] as const;

function AdminRouteContent({children}:{children:ReactNode}){const content=useRef<HTMLDivElement>(null),[ready,setReady]=useState(false);useLayoutEffect(()=>{const node=content.current;if(!node)return;const check=()=>{if(!node.querySelector('.brand-loader'))setReady(true)};check();if(!node.querySelector('.brand-loader'))return;const observer=new MutationObserver(check);observer.observe(node,{childList:true,subtree:true});return()=>observer.disconnect()},[]);return <><div className="admin-route-content" ref={content} style={{visibility:ready?'visible':'hidden'}}>{children}</div>{!ready&&<div className="admin-route-loader"><BrandLoader label="Loading section"/></div>}</>}
function Admin(){const loc=useLocation();const[collapsed,setCollapsed]=useState(false),[mobileNav,setMobileNav]=useState(false);const[staff,setStaff]=useState<Staff|null>(null),[loading,setLoading]=useState(true),[denied,setDenied]=useState(false);useEffect(()=>{let live=true;(async()=>{if(!supabase){setDenied(true);setLoading(false);return}const{data:{user}}=await supabase.auth.getUser();if(!user){setLoading(false);return}const[{data:profile,error:profileError},{data:permissions,error:permissionsError},{data:userRoles}]=await Promise.all([supabase.from('profiles').select('full_name,active').eq('id',user.id).single(),supabase.rpc('my_permissions'),supabase.from('user_roles').select('roles(name)').eq('user_id',user.id)]);if(!live)return;if(profileError||permissionsError||!profile?.active){setDenied(true);setLoading(false);return}const role=(userRoles?.[0] as any)?.roles?.name||'Staff';setStaff({user,profile,permissions:(permissions||[]) as string[],role});setLoading(false)})();return()=>{live=false}},[]);if(loading)return <div className="admin-loading"><BrandLoader label="Loading workspace"/></div>;if(!staff&&!denied)return <Navigate to="/login" replace/>;if(denied)return <main className="login-wrap"><div className="login-card"><h1>Access unavailable</h1><p>This account is not an active YAQEEN staff account.</p><button className="primary-button" onClick={()=>supabase?.auth.signOut().then(()=>location.href='/YaqeenShop/login')}>Sign out</button></div></main>;return <div className={'admin '+(collapsed?'sidebar-collapsed':'')+(mobileNav?' mobile-nav-open':'')}><div className="admin-mobile-bar"><button className="admin-mobile-menu icon-button" aria-label="Open workspace menu" onClick={()=>setMobileNav(true)}><Menu size={22}/></button><span className="admin-mobile-title">YAQEEN</span></div>{mobileNav&&<button className="admin-nav-backdrop" aria-label="Close workspace menu" onClick={()=>setMobileNav(false)}/>}<aside className="sidebar"><div className="mobile-sidebar-head"><Brand/><button className="icon-button mobile-nav-close" aria-label="Close workspace menu" onClick={()=>setMobileNav(false)}>×</button></div><Brand/><button className="icon-button sidebar-toggle" aria-expanded={!collapsed} aria-label={collapsed?'Expand sidebar':'Collapse sidebar'} onClick={()=>setCollapsed(!collapsed)}>{collapsed?<ChevronRight size={20}/>:<ChevronLeft size={20}/>}</button><nav>{links.filter(l=>!l[2]||staff!.permissions.includes(l[2])).map(([label,path,,Icon])=>{const target='/admin/'+path;const active=loc.pathname===target||(path&&loc.pathname.startsWith(target+'/'));return <Link onClick={()=>setMobileNav(false)} aria-current={active?'page':undefined} key={path} to={target} data-tooltip={label} aria-label={label}><Icon size={17}/><span>{label}</span></Link>})}</nav><div className="sidebar-account"><div className="sidebar-user"><strong>{staff!.profile.full_name||staff!.user.email}</strong><span>{staff!.role}</span></div><Link className="sidebar-store-link" to="/" onClick={()=>setMobileNav(false)}><Globe size={15}/><span>View store</span></Link><button className="secondary-button" onClick={async()=>{await supabase?.auth.signOut();location.href='/YaqeenShop/login'}}>Sign out</button></div></aside><div className="admin-main"><main id="main"><AdminRouteContent key={loc.pathname}><Routes><Route path="" element={<Dashboard permissions={staff!.permissions}/>}/><Route path="categories" element={<Categories permissions={staff!.permissions}/>}/><Route path="products" element={<ProductsAdmin permissions={staff!.permissions}/>}/><Route path="inventory" element={<InventoryAdmin permissions={staff!.permissions}/>}/><Route path="designs" element={<DesignsAdmin permissions={staff!.permissions}/>}/><Route path="orders" element={<OrdersAdmin permissions={staff!.permissions}/>}/><Route path="customers" element={<CustomersAdmin permissions={staff!.permissions}/>}/><Route path="production" element={<ProductionAdmin permissions={staff!.permissions}/>}/><Route path="deliveries" element={<FulfillmentAdmin kind="deliveries" permissions={staff!.permissions}/>}/><Route path="payments" element={<FulfillmentAdmin kind="payments" permissions={staff!.permissions}/>}/><Route path="inbox" element={<InboxAdmin/>}/><Route path="users" element={<UsersRoles permissions={staff!.permissions}/>}/><Route path="audit" element={<AuditLog/>}/><Route path="website" element={<WebsiteAdmin permissions={staff!.permissions}/>}/><Route path="reports" element={<Reports/>}/><Route path="settings" element={<SettingsAdmin permissions={staff!.permissions}/>}/><Route path="*" element={<section className="admin-page"><h1>Module migration</h1><p>This CRM section is being migrated.</p></section>}/></Routes></AdminRouteContent></main></div></div>}

const PUBLIC_ORIGIN='https://shereenakoum.github.io';
const PUBLIC_BASE='/YaqeenShop';
function SeoMetadata(){const loc=useLocation();useEffect(()=>{if(loc.pathname.startsWith('/admin')||loc.pathname==='/login')return;const path=loc.pathname||'/';const labels:Record<string,[string,string]>={'/':['YAQEEN — A more meaningful life','Thoughtful Islamic acrylic reminders designed to bring faith, meaning and intention into everyday life.'],'/shop':['Shop meaningful Islamic reminders | YAQEEN','Explore YAQEEN’s collection of thoughtful Islamic acrylic reminders and meaningful gifts.'],'/cart':['Your bag | YAQEEN','Review the meaningful reminders in your YAQEEN shopping bag.'],'/checkout':['Secure checkout | YAQEEN','Complete your YAQEEN order securely and provide your delivery details.'],'/order-confirmation':['Order confirmation | YAQEEN','Your YAQEEN order confirmation and next steps.'],'/search':['Search the collection | YAQEEN','Search YAQEEN for thoughtful Islamic acrylic reminders and meaningful gifts.'],'/about':['About YAQEEN | A more meaningful life','Discover the story and intention behind YAQEEN and our meaningful Islamic reminders.'],'/contact':['Contact YAQEEN','Get in touch with YAQEEN for product, order or delivery questions.'],'/faq':['Frequently asked questions | YAQEEN','Find answers to common questions about YAQEEN products, orders, payment and delivery.'],'/privacy':['Privacy Policy | YAQEEN','Read how YAQEEN handles information and browser storage when you use the storefront.'],'/terms':['Terms & Conditions | YAQEEN','Read the terms that apply when using the YAQEEN storefront and placing an order.'],'/under-construction':['Coming soon | YAQEEN','Something meaningful is taking shape at YAQEEN. This page will be available soon.']};let [title,description]=labels[path]||[path.startsWith('/products/')?'Islamic acrylic reminder | YAQEEN':'YAQEEN — A more meaningful life','Thoughtful Islamic acrylic reminders for a more meaningful life.'];document.title=title;const canonical=PUBLIC_ORIGIN+PUBLIC_BASE+(path==='/'?'/':path);const set=(selector:string,attr:string,value:string)=>{let el=document.head.querySelector<HTMLMetaElement>(selector);if(!el){el=document.createElement('meta');if(selector.includes('property='))el.setAttribute('property',selector.match(/property="([^"]+)/)?.[1]||'');else el.name=selector.match(/name="([^"]+)/)?.[1]||'';document.head.appendChild(el)}el.setAttribute(attr,value)};set('meta[name="description"]','content',description);set('meta[property="og:title"]','content',title);set('meta[property="og:description"]','content',description);set('meta[property="og:type"]','content',path.startsWith('/products/')?'product':'website');set('meta[property="og:url"]','content',canonical);set('meta[property="og:site_name"]','content','YAQEEN');set('meta[name="twitter:card"]','content','summary_large_image');set('meta[name="twitter:title"]','content',title);set('meta[name="twitter:description"]','content',description);let link=document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.appendChild(link)}link.href=canonical},[loc.pathname]);return null}

function Analytics(){const loc=useLocation();const[id,setId]=useState('');const[allowed,setAllowed]=useState(()=>{try{return localStorage.getItem('yaqeen-cookie-consent')==='accepted'}catch{return false}});useEffect(()=>{const onConsent=(event:Event)=>setAllowed((event as CustomEvent<string>).detail==='accepted');window.addEventListener('cookieconsentchange',onConsent);if(supabase)void supabase.from('site_settings').select('value').eq('key','website').maybeSingle().then(({data})=>setId(String(data?.value?.ga_measurement_id||data?.value?.google_analytics_id||'').trim()));return()=>window.removeEventListener('cookieconsentchange',onConsent)},[]);useEffect(()=>{if(!allowed||!/^G-[A-Z0-9]+$/i.test(id))return;const w=window as any;w.dataLayer=w.dataLayer||[];w.gtag=w.gtag||function(){w.dataLayer.push(arguments)};if(!document.querySelector('script[data-yaqeen-ga]')){const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(id);script.dataset.yaqeenGa='true';document.head.appendChild(script);w.gtag('js',new Date());w.gtag('config',id,{send_page_view:false,anonymize_ip:true})}w.gtag('event','page_view',{page_title:document.title,page_location:window.location.href,page_path:loc.pathname+loc.search})},[allowed,id,loc.pathname,loc.search]);return null}

function SiteFavicon(){useEffect(()=>{let live=true;const apply=(value:string)=>{let link=document.querySelector<HTMLLinkElement>('link[rel="icon"]');if(!value){link?.remove();return}if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=value};const onChange=(event:Event)=>apply((event as CustomEvent<string>).detail);window.addEventListener('sitefaviconchange',onChange);if(supabase)void supabase.from('site_settings').select('value').eq('key','website').maybeSingle().then(({data})=>{if(live)apply(data?.value?.favicon_url||'')});return()=>{live=false;window.removeEventListener('sitefaviconchange',onChange)}},[]);return null}
export default function App(){return <><SiteFavicon/><SeoMetadata/><Analytics/><Routes><Route path="/login" element={<Login/>}/><Route path="/admin/*" element={<Admin/>}/><Route path="*" element={<><Header/><main id="main"><Routes><Route path="/" element={<Home/>}/><Route path="/shop" element={<Products/>}/><Route path="/products/:slug" element={<ProductPage/>}/><Route path="/cart" element={<CartPage/>}/><Route path="/checkout" element={<CheckoutPage/>}/><Route path="/order-confirmation" element={<ConfirmationPage/>}/><Route path="/search" element={<SearchPage/>}/><Route path="/privacy" element={<LegalPage kind="privacy"/>}/><Route path="/terms" element={<LegalPage kind="terms"/>}/><Route path="/under-construction" element={<UnderConstruction/>}/><Route path="/:page" element={<ContentPage/>}/><Route path="*" element={<NotFound/>}/></Routes></main><Footer/><CookieConsent/></>}/></Routes></>}
